SELECT
to_char( platform_create_time, 'yyyy-mm' ) AS MONTH,
round( SUM ( order_fee * currency_rate ) / 10000, 4 ) AS "orderSales"
FROM dmp_order_info o



            o.paid_time >= #{params.startTime}


            AND o.paid_time <= #{params.endTime}





            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time <= #{params.endTime}




        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_no IN

            #{shopNo}




        AND o.charge_id IN

            #{userId}




        #{params.param}


GROUP BY MONTH ORDER BY MONTH ASC

SELECT
(SELECT name_cn FROM dmp_sku_info ds WHERE ds.sku_no = i.sku_no LIMIT 1 ) productName,
SUM ( i.quantity ) AS salesQuantity,
COUNT(DISTINCT ( i.order_id ))  AS orderCount,
round( SUM ( ( i.sell_price * i.quantity * i.currency_rate ) ) / 10000, 4 ) sales,
i.sku_no AS name FROM dmp_order_item i
LEFT JOIN dmp_order_info o ON i.order_id = o.ID



            o.paid_time >= #{params.startTime}


            AND o.paid_time <= #{params.endTime}





            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time <= #{params.endTime}




        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_no IN

            #{shopNo}




        AND i.platform_sku IN

            #{sku}




        AND i.category_id IN

            #{category}




        AND i.brand_id IN

            #{brand}




        AND o.charge_id IN

            #{userId}




        #{params.param}


GROUP BY sku_no
ORDER BY sales ASC

